#include <stdio.h>

int bowl = {v};

int take_one(void) {
    bowl = bowl + 1;
    return bowl;
}

int bigger(int a, int b) {
    return a > b ? a : b;
}

int main(void) {
    int biggest = bigger(take_one(), 2);
    printf("挑出来的是 %d\n", biggest);
    printf("鱼缸里现在是 %d\n", bowl);
    return 0;
}
